&lt;div class="msgHead"&gt;
&lt;h1&gt;
&lt;span class="subject"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=subject:%22%5C%5Bblink%5C-dev%5C%5D+Intent+to+Prototype%5C%3A+JavaScript+call+stacks+in+out%5C-of%5C-memory+%5C%28OOM%5C%29+crash+reports%22&amp;o=newest" rel="nofollow"&gt;&lt;span itemprop="name"&gt;[blink-dev] Intent to Prototype: JavaScript call stacks in out-of-memory (OOM) crash reports&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
&lt;/h1&gt;
&lt;p class="darkgray font13"&gt;
&lt;span class="sender pipe"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=from:%22Chromestatus%22" rel="nofollow"&gt;&lt;span itemprop="author" itemscope itemtype="http://schema.org/Person"&gt;&lt;span itemprop="name"&gt;Chromestatus&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
